import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = []
    for i in range(1, 2 * n + 1):
        a.append(int(input_data[i]))

    a.sort()

    sum_first = sum(a[:n])
    sum_last = sum(a[n:])

    if sum_first != sum_last:
        print(*(a))
    else:
        print("-1")

if __name__ == "__main__":
    solve()
